import{_ as t,o as a,c as s,ag as o}from"./chunks/framework.B3IQijK_.js";const u=JSON.parse('{"title":"Automation tools","description":"Choose and manage watches, employee workflows, backtest jobs, and paper-position monitoring.","frontmatter":{"title":"Automation tools","description":"Choose and manage watches, employee workflows, backtest jobs, and paper-position monitoring.","outline":2,"head":[["link",{"rel":"canonical","href":"https://tradecli.in/wiki/trading-office/watches"}]]},"headers":[],"relativePath":"trading-office/watches.md","filePath":"trading-office/watches.md"}'),n={name:"trading-office/watches.md"};function i(r,e,l,c,h,p){return a(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="automation-tools" tabindex="-1">Automation tools <a class="header-anchor" href="#automation-tools" aria-label="Permalink to &quot;Automation tools&quot;">​</a></h1><p>Trading Office can continue observing, researching, testing, and managing paper positions after the initial instruction. The right automation tool depends on whether the work requires AI interpretation, a standing employee responsibility, experiment continuation, or a recorded position rule.</p><h2 id="choose-the-right-tool" tabindex="-1">Choose the right tool <a class="header-anchor" href="#choose-the-right-tool" aria-label="Permalink to &quot;Choose the right tool&quot;">​</a></h2><table tabindex="0"><thead><tr><th>If you want to…</th><th>Use…</th></tr></thead><tbody><tr><td>Re-check a chart, thesis, news condition, or exposure and report what changed</td><td><strong>Watch</strong></td></tr><tr><td>Give an employee a recurring responsibility with scope and risk limits</td><td><strong>Office workflow</strong></td></tr><tr><td>Run an approved experiment in durable, resumable chunks</td><td><strong>Backtest job</strong></td></tr><tr><td>Apply recorded stops, targets, and time exits to a paper position</td><td><strong>Position monitor</strong></td></tr></tbody></table><p>A conventional market watchlist only groups symbols for browsing. A Trading Office watch schedules an AI employee to gather fresh context, interpret it, and report meaningful changes.</p><h2 id="watches" tabindex="-1">Watches <a class="header-anchor" href="#watches" aria-label="Permalink to &quot;Watches&quot;">​</a></h2><p>A watch is useful when one answer is not enough. You might follow a price level, thesis, portfolio condition, filing, or research question over time.</p><h3 id="start-a-watch-in-natural-language" tabindex="-1">Start a watch in natural language <a class="header-anchor" href="#start-a-watch-in-natural-language" aria-label="Permalink to &quot;Start a watch in natural language&quot;">​</a></h3><p>Tell the active employee what to watch, how often to check, and which changes matter:</p><p class="doc-code-label">Example watch</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Watch RELIANCE every 5 minutes. Report only if it closes above 3,100</span></span>
<span class="line"><span>with stronger volume, or if the setup is invalidated below 3,050.</span></span></code></pre></div><p class="doc-code-label">Example watch</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Watch our technology exposure every hour and tell me if it rises above 30%.</span></span></code></pre></div><p class="doc-code-label">Example watch</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Watch this earnings thesis once a day. Compare new filings and news with</span></span>
<span class="line"><span>the current thesis, and save a research record only when something material changes.</span></span></code></pre></div><p>A useful watch instruction defines:</p><ul><li>the symbol, book, thesis, exposure, or source to check;</li><li>the interval between checks;</li><li>the current baseline;</li><li>the changes worth reporting; and</li><li>whether a material result should become a durable Office record.</li></ul><p>The response includes a <strong>cron job ID</strong>. Keep it as the reliable identifier for inspecting, stopping, or deleting the watch.</p><h3 id="what-happens-on-each-check" tabindex="-1">What happens on each check <a class="header-anchor" href="#what-happens-on-each-check" aria-label="Permalink to &quot;What happens on each check&quot;">​</a></h3><p>At each tick, the employee reloads the instruction, gathers fresh context through the appropriate market, browser, broker, or TradingView tools, compares it with the baseline, and reports the useful difference.</p><p>A watch polls rather than streams. Its minimum interval is <strong>one minute</strong>. Each watch runs <strong>10 times by default</strong> and then pauses itself; request a different run cap when you create it if the job should continue longer.</p><p>The schedule and prompt persist locally. Decision-relevant results can also be preserved as research records when the instruction asks for it.</p><h3 id="list-stop-and-delete-watches" tabindex="-1">List, stop, and delete watches <a class="header-anchor" href="#list-stop-and-delete-watches" aria-label="Permalink to &quot;List, stop, and delete watches&quot;">​</a></h3><p>Use natural language with the cron job ID:</p><p class="doc-code-label">Request</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>List my watches.</span></span></code></pre></div><p class="doc-code-label">Request</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Stop watch &lt;cron-job-id&gt;.</span></span></code></pre></div><p class="doc-code-label">Request</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Delete watch &lt;cron-job-id&gt;.</span></span></code></pre></div><ul><li><strong>List</strong> shows ownership, state, interval, next and previous run, last status, and run count.</li><li><strong>Stop</strong> pauses the watch while keeping its stored job.</li><li><strong>Delete</strong> permanently removes the scheduled job.</li></ul><p>The employee who creates a watch owns it, and its ticks return to that employee&#39;s pane. The office lead can inspect and remove watches across the office through Cron Monitor.</p><h3 id="inspect-watches-in-cron-monitor" tabindex="-1">Inspect watches in Cron Monitor <a class="header-anchor" href="#inspect-watches-in-cron-monitor" aria-label="Permalink to &quot;Inspect watches in Cron Monitor&quot;">​</a></h3><p>Run:</p><p class="doc-code-label">Command</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/crons</span></span></code></pre></div><p>The <strong>WATCHES</strong> table shows each job&#39;s owner, schedule, next run, previous run, and state:</p><ul><li><strong>ARMED</strong> — enabled and waiting for the next check;</li><li><strong>PAUSED</strong> — disabled manually or after reaching its run cap;</li><li><strong>ERROR</strong> — the previous check failed.</li></ul><p>Use <code>↑</code> and <code>↓</code> to select a row, <code>R</code> to refresh, and <code>K</code> or <code>X</code> to remove the selected watch after confirmation. Removing deletes the job; use <strong>Stop watch</strong> in conversation when you want to keep it.</p><h2 id="office-workflows" tabindex="-1">Office workflows <a class="header-anchor" href="#office-workflows" aria-label="Permalink to &quot;Office workflows&quot;">​</a></h2><p>An Office workflow is a standing responsibility owned by an employee. It has a cadence, scope, mandate, and persisted run history. Examples include a Trader scanning an approved universe, a Risk Manager reviewing exposure, or an Investor updating a research brief.</p><p>Create, inspect, pause, and restart workflows from the Control Center:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/hedgefund:control</span></span></code></pre></div><p>Guided operation keeps scheduled employee ticks paused. Autonomous · Paper trading allows due workflows to run within their mandates and report their results.</p><h2 id="backtest-jobs" tabindex="-1">Backtest jobs <a class="header-anchor" href="#backtest-jobs" aria-label="Permalink to &quot;Backtest jobs&quot;">​</a></h2><p>A backtest job executes the experiment approved in Strategy Lab. It stores each completed chunk, so a long test can resume without losing finished work.</p><p>Inspect experiments through <strong>Backtest Lab → Jobs</strong>. The workflow heartbeat is the internal background mechanism that discovers unfinished experiment chunks and due Office work; it is not a user-created automation type.</p><h2 id="position-monitor" tabindex="-1">Position monitor <a class="header-anchor" href="#position-monitor" aria-label="Permalink to &quot;Position monitor&quot;">​</a></h2><p>The position monitor works from the exit plan recorded on an Office paper position. It checks stops, targets, planned time exits, and applicable intraday cutoffs using current market data.</p><p>Use Market Terminal to inspect the position or make a manual partial or full exit:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/terminal</span></span></code></pre></div><h2 id="when-automation-needs-attention" tabindex="-1">When automation needs attention <a class="header-anchor" href="#when-automation-needs-attention" aria-label="Permalink to &quot;When automation needs attention&quot;">​</a></h2><ul><li><strong>Watch reaches its run cap</strong> — it pauses after its configured number of runs. Create a new watch only when further checks are required.</li><li><strong>Watch shows ERROR</strong> — inspect its last status in Cron Monitor before deleting or replacing it.</li><li><strong>Employee workflow fails or waits</strong> — inspect recent activity in Control Center. Pause the workflow when its data, mandate, or scope needs correction.</li><li><strong>Backtest stops advancing</strong> — inspect the saved job in Backtest Lab. Do not create a duplicate while the original job still exists.</li><li><strong>Position mark is unavailable</strong> — keep the recorded position and restore its connected price source; the system should not invent a mark.</li></ul><h2 id="related-pages" tabindex="-1">Related pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related pages&quot;">​</a></h2><ul><li><a href="/trading-sandbox-website-preview/wiki/trading-office/setup">Set up your office</a></li><li><a href="/trading-sandbox-website-preview/wiki/trading-office/strategy-lab">Test in Strategy Lab</a></li><li><a href="/trading-sandbox-website-preview/wiki/trading-office/paper-operations">Paper trade and monitor</a></li><li><a href="/trading-sandbox-website-preview/wiki/trading-office/operations">Run your trading office</a></li><li><a href="/trading-sandbox-website-preview/wiki/trading-office/concepts">Concepts and terminology</a></li><li><a href="/trading-sandbox-website-preview/wiki/trading-office/commands">Commands and shortcuts</a></li></ul>`,55)])])}const g=t(n,[["render",i]]);export{u as __pageData,g as default};
